import{_ as a,o as s,c as i,ag as d}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"WaitDI8421 等待8421码数字量输入","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/WaitDI8421.md","filePath":"3. 指令/4. IO 指令/WaitDI8421.md","lastUpdated":1778862643000}'),r={name:"3. 指令/4. IO 指令/WaitDI8421.md"};function n(e,t,o,l,h,p){return s(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="waitdi8421-等待8421码数字量输入" tabindex="-1">WaitDI8421 等待8421码数字量输入 <a class="header-anchor" href="#waitdi8421-等待8421码数字量输入" aria-label="Permalink to &quot;WaitDI8421 等待8421码数字量输入&quot;">​</a></h1><h3 id="waitdi8421" tabindex="-1"><strong>WaitDI8421</strong> <a class="header-anchor" href="#waitdi8421" aria-label="Permalink to &quot;**WaitDI8421**&quot;">​</a></h3><p>该指令用于在指定时长内监控一组<strong>连续的数字量输入（DI）端口</strong>。它会将这些端口的二进制状态组合转换成一个十进制数，并与设定的目标值进行比对。这种方式常用于读取拨码开关状态、从 PLC 获取多位编码信号或传感器阵列的组合逻辑。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>WaitDI8421 (T, BEGINPORT, ENDPORT, VALUE, INTERENABLE, RET, [Goto])</code></p><p><code>WaitDI8421(超时时间, 起始端口, 结束端口, 目标十进制值, 打断使能, 结果变量, [跳转行号])</code></p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>T</td><td>int 或 INT 变量</td><td>等待限时，单位 ms（0：强制等待直到信号满足）</td><td>必填</td></tr><tr><td>BEGINPORT</td><td>int</td><td>连续 DI 端口段的起始编号</td><td>必填</td></tr><tr><td>ENDPORT</td><td>int</td><td>连续 DI 端口段的结束编号</td><td>必填</td></tr><tr><td>VALUE</td><td>int 或 INT 变量</td><td>目标十进制数值，端口状态组合与此值比较</td><td>必填</td></tr><tr><td>INTERENABLE</td><td>int</td><td>程序暂停恢复后的计时逻辑（0：继续计时，1：重新计时）</td><td>必填</td></tr><tr><td>RET</td><td>INT 变量</td><td>返回指令执行结束后的状态（0：成功，1：超时）</td><td>必填</td></tr><tr><td>[Goto]</td><td>label</td><td>超时后程序指针跳转到的指定标签名</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">WaitDI8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析：</strong></p><ol><li><strong>监控范围</strong>：监控从 <strong>9 号</strong> 到 <strong>16 号</strong> 的连续 8 个 DI 端口。</li><li><strong>判断条件</strong>：目标值为 <strong>255</strong>。在二进制中，8 位全为 1（即 <code>1111 1111</code>）时，十进制恰好为 255。这意味着要求 9 到 16 号端口必须<strong>全部为高电平</strong>。</li><li><strong>等待机制</strong>：最长等待 <strong>1000ms</strong>。</li><li><strong>中断逻辑</strong>：由于 <code>INTERENABLE</code> 为 <strong>1</strong>，若等待过程中程序暂停，恢复后计时器将<strong>重置并重新开始</strong> 1000ms 的计时。</li><li><strong>结果处理</strong>：若 1000ms 内条件满足，程序继续；若超时未满足，则将 <strong>INT1</strong> 置为 <strong>1</strong>。</li></ol>',16)])])}const E=a(r,[["render",n]]);export{k as __pageData,E as default};
